"use strict";

// The THROW half of the same defect. An uncaught throw at module scope
// aborts module evaluation exactly as `return` does: `require()` itself
// throws, and the value `module.exports` was left holding is whatever the
// throwing branch had already written. The final assignment below is
// again syntactically unconditional and again does not always run.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  throw new Error("fast mode is not supported here");
}

module.exports = safeOp;
